import xml.etree.ElementTree as ET
import requests
import time
from collections import deque
import sys

class FeedAggregator:
    def __init__(self):
        self.semaphore = deque()
        self.request_queue = deque()
        self.last_request_time = time.time()
        self.max_concurrent = 2
        self.max_requests_per_second = 5

    def process_feed(self, url):
        try:
            response = requests.get(url, timeout=10)
            response.raise_for_status()
            root = ET.fromstring(response.text)
            for item in root.findall('.//item') + root.findall('.//entry'):
                title = item.find('title')
                if title is not None:
                    yield f"{url}|{title.text}"
        except requests.RequestException as e:
            sys.stderr.write(f"ERROR {url}: {str(e)}\n")

    def worker(self):
        while True:
            if not self.request_queue:
                time.sleep(0.1)
                continue

            url = self.request_queue.popleft()
            start_time = time.time()

            try:
                for title in self.process_feed(url):
                    self.semaphore.append(title)
            except Exception as e:
                sys.stderr.write(f"ERROR {url}: {str(e)}\n")

            elapsed = time.time() - start_time
            while len(self.semaphore) >= self.max_concurrent:
                time.sleep(0.1)

            if len(self.semaphore) < self.max_concurrent:
                self.semaphore.append(None)

            if time.time() - self.last_request_time >= 1:
                self.last_request_time = time.time()
                self.request_queue = deque(self.request_queue, maxlen=self.max_requests_per_second)

    def start_workers(self, num_workers=2):
        for _ in range(num_workers):
            thread = threading.Thread(target=self.worker)
            thread.daemon = True
            thread.start()

    def process_feeds(self, feeds_xml):
        tree = ET.parse(feeds_xml)
        root = tree.getroot()
        for feed in root.findall('feed'):
            url = feed.get('url')
            self.request_queue.append(url)

    def run(self):
        import threading
        self.start_workers()
        while self.request_queue:
            time.sleep(0.1)

        while self.semaphore:
            time.sleep(0.1)

        for title in self.semaphore:
            if title is not None:
                print(title)

def main():
    aggregator = FeedAggregator()
    try:
        aggregator.process_feeds('feeds.xml')
        aggregator.run()
    except Exception as e:
        sys.stderr.write(f"ERROR: {str(e)}\n")

if __name__ == "__main__":
    main()

import xml.etree.ElementTree as ET
import requests
from urllib.parse import urlparse
from concurrent.futures import ThreadPoolExecutor, as_completed
import time
from collections import deque

FEEDS_XML = 'feeds.xml'
REQUEST_LIMIT = 5
REQUEST_WINDOW = 1
MAX_IN_FLIGHT = 2

def parse_feeds():
    try:
        with open(FEEDS_XML, 'r', encoding='utf-8') as f:
            return ET.fromstring(f.read())
    except Exception as e:
        print(f"Error reading {FEEDS_XML}: {e}")
        return None

def fetch_feed_url(url):
    try:
        response = requests.get(url, timeout=10)
        response.raise_for_status()
        return response.text
    except Exception as e:
        print(f"Failed to fetch {url}: {e}")
        return None

def parse_items(xml_content):
    try:
        root = ET.fromstring(xml_content)
        titles = []
        for item in root.findall('.//item') + root.findall('.//entry'):
            title = item.find('title')
            if title is not None:
                titles.append(title.text)
        return titles
    except Exception as e:
        print(f"Error parsing items: {e}")
        return []

def process_feed(feed_url):
    xml_content = fetch_feed_url(feed_url)
    if xml_content is None:
        return
    titles = parse_items(xml_content)
    for title in titles:
        print(f"{feed_url}|{title}")

def rate_limited_executor(futures):
    last_request_time = time.time()
    in_flight = deque()

    def executor():
        nonlocal last_request_time
        while True:
            if len(in_flight) < MAX_IN_FLIGHT:
                if len(futures) > 0:
                    future = futures.popleft()
                    in_flight.append(future)
                    yield future
                else:
                    break
            else:
                current_time = time.time()
                time_since_last = current_time - last_request_time
                if time_since_last >= REQUEST_WINDOW:
                    last_request_time = current_time
                    if len(futures) > 0:
                        future = futures.popleft()
                        in_feed = deque(in_flight)
                        in_feed.append(future)
                        in_flight = in_feed
                        yield future
                else:
                    time.sleep(REQUEST_WINDOW - time_since_last)

    return executor()

def main():
    feeds = parse_feeds()
    if not feeds:
        return

    feed_urls = []
    for feed in feeds.findall('feed'):
        url = feed.get('url')
        if url:
            feed_urls.append(url)

    futures = []
    with ThreadPoolExecutor(max_workers=2) as executor:
        for url in feed_urls:
            future = executor.submit(process_feed, url)
            futures.append(future)

        for future in rate_limited_executor(futures):
            try:
                future.result()
            except Exception as e:
                print(f"Error processing feed: {e}")

if __name__ == "__main__":
    main()

import requests
import xml.etree.ElementTree as ET
import time
from urllib.parse import urlparse
from threading import Lock
from queue import Queue

class RateLimiter:
    def __init__(self):
        self.requests = Queue()
        self.lock = Lock()
        self.last_request_time = 0

    def can_make_request(self):
        with self.lock:
            current_time = time.time()
            if current_time - self.last_request_time >= 1:
                self.last_request_time = current_time
                return True
            if self.requests.qsize() < 5:
                return True
            return False

    def make_request(self):
        with self.lock:
            self.requests.put(time.time())
            return True

    def wait_for_request(self):
        with self.lock:
            while self.requests.qsize() >= 5:
                time.sleep(0.1)

