import xml.etree.ElementTree as ET
import requests
import time
from urllib.parse import urlparse
from concurrent.futures import ThreadPoolExecutor, as_completed

def process_feed(feed_url, feed_urls):
    try:
        response = requests.get(feed_url, timeout=10)
        response.raise_for_status()
        root = ET.fromstring(response.text)
        for item in root.findall('.//item'):
            title = item.find('title')
            if title is not None:
                print(f"{feed_url}|{title.text.strip()}")
    except (requests.RequestException, ET.ParseError):
        pass

def main():
    feed_urls = []
    with open('feeds.xml', 'r', encoding='utf-8') as f:
        tree = ET.parse(f)
        root = tree.getroot()
        for feed in root.findall('feed'):
            feed_url = feed.get('url')
            if feed_url:
                feed_urls.append(feed_url)

    max_requests = 5
    max_concurrent = 1
    current_requests = 0
    last_request_time = time.time()

    with ThreadPoolExecutor(max_workers=max_concurrent) as executor:
        futures = []
        for feed_url in feed_urls:
            future = executor.submit(process_feed, feed_url, feed_urls)
            futures.append(future)

            # Enforce rate limits
            while len(futures) >= max_requests:
                oldest_future = min(futures, key=lambda f: f._future._state)
                if oldest_future._state == 'STARTED':
                    time.sleep(1)
                else:
                    break

            if current_requests >= max_concurrent:
                time.sleep(1)

            current_requests += 1

        for future in as_completed(futures):
            try:
                future.result()
            except Exception as e:
                print(f"Error processing feed: {e}")
            finally:
                current_requests -= 1
                if current_requests < max_concurrent:
                    time.sleep(1)

if __name__ == "__main__":
    main()
